"""
Base pattern class for the Python research lab.
"""
from abc import ABC, abstractmethod
from dataclasses import dataclass
from typing import Optional, List, Dict, Any
import pandas as pd


@dataclass
class Signal:
    """Trading signal generated by a pattern."""
    pattern_id: str
    pattern_name: str
    direction: str  # 'LONG' or 'SHORT'
    timestamp: pd.Timestamp
    entry_price: float
    stop_loss: float
    target: float
    confidence: float
    confluence_factors: List[str]
    risk_reward_ratio: float
    
    def to_dict(self) -> Dict[str, Any]:
        return {
            'pattern_id': self.pattern_id,
            'pattern_name': self.pattern_name,
            'direction': self.direction,
            'timestamp': self.timestamp,
            'entry_price': self.entry_price,
            'stop_loss': self.stop_loss,
            'target': self.target,
            'confidence': self.confidence,
            'confluence_factors': self.confluence_factors,
            'risk_reward_ratio': self.risk_reward_ratio,
        }


class BasePattern(ABC):
    """
    Abstract base class for all patterns.
    Patterns implement detect_signal() to identify trading opportunities.
    """
    
    def __init__(self, config: Optional[Dict[str, Any]] = None):
        self.config = config or {}
        self.enabled = True
    
    @property
    @abstractmethod
    def id(self) -> str:
        """Unique pattern identifier."""
        pass
    
    @property
    @abstractmethod
    def name(self) -> str:
        """Human-readable pattern name."""
        pass
    
    @property
    def description(self) -> str:
        """Pattern description."""
        return ""
    
    @property
    def version(self) -> str:
        """Pattern version."""
        return "1.0.0"
    
    @abstractmethod
    def detect_signal(
        self,
        df: pd.DataFrame,
        symbol: str = "",
    ) -> Optional[Signal]:
        """
        Detect if pattern conditions are met.
        
        Args:
            df: OHLCV DataFrame with at least required_bars rows
            symbol: Trading symbol
        
        Returns:
            Signal if pattern detected, None otherwise
        """
        pass
    
    @abstractmethod
    def calculate_stop_loss(
        self,
        entry_price: float,
        direction: str,
        df: pd.DataFrame,
    ) -> float:
        """Calculate stop-loss price."""
        pass
    
    def calculate_target(
        self,
        entry_price: float,
        stop_loss: float,
        direction: str,
        df: pd.DataFrame,
        target_rr: float = 2.0,
    ) -> float:
        """Calculate target price based on risk-reward ratio."""
        risk = abs(entry_price - stop_loss)
        
        if direction == 'LONG':
            return entry_price + (risk * target_rr)
        else:
            return entry_price - (risk * target_rr)
    
    @abstractmethod
    def get_required_bars(self) -> int:
        """Minimum number of bars required for pattern detection."""
        pass
    
    def validate(self, df: pd.DataFrame) -> bool:
        """Validate that DataFrame has enough data."""
        return len(df) >= self.get_required_bars()

